package zw.ac.uz.emhare.assessmentresults.result;
import jakarta.persistence.*;import java.math.BigDecimal;import org.hibernate.annotations.SQLRestriction;import org.hibernate.envers.Audited;import zw.ac.uz.emhare.common.persistence.AuditableEntity;
/** @author Tinashe K */
@Audited @Entity @Table(name="grading_bands") @SQLRestriction("deleted_at IS NULL")
public class GradingBand extends AuditableEntity{
 @ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="grading_scheme_id")private GradingScheme gradingScheme;@Column(name="minimum_mark",nullable=false,precision=6,scale=2)private BigDecimal minimumMark;@Column(name="maximum_mark",nullable=false,precision=6,scale=2)private BigDecimal maximumMark;@Column(nullable=false,length=10)private String grade;@Column(nullable=false,length=100)private String remark;@Column(nullable=false)private boolean passing;@Column(name="sort_order",nullable=false)private int sortOrder;
 protected GradingBand(){}public GradingBand(GradingScheme scheme,BigDecimal min,BigDecimal max,String grade,String remark,boolean passing,int order){if(min==null||max==null||min.signum()<0||max.compareTo(BigDecimal.valueOf(100))>0||max.compareTo(min)<0)throw new IllegalArgumentException("Grading band range must be within 0 to 100.");if(order<1)throw new IllegalArgumentException("Sort order must be positive.");gradingScheme=scheme;minimumMark=min;maximumMark=max;this.grade=GradingScheme.text(grade).toUpperCase();this.remark=GradingScheme.text(remark);this.passing=passing;sortOrder=order;}
 public boolean contains(BigDecimal mark){return mark.compareTo(minimumMark)>=0&&mark.compareTo(maximumMark)<=0;}public GradingScheme getGradingScheme(){return gradingScheme;}public BigDecimal getMinimumMark(){return minimumMark;}public BigDecimal getMaximumMark(){return maximumMark;}public String getGrade(){return grade;}public String getRemark(){return remark;}public boolean isPassing(){return passing;}public int getSortOrder(){return sortOrder;}
}
